import java.util.Scanner;

public class Main {
    static final int MOD_CONST = 1000000007;

    static int modPow(int base, int exp) {
        if (exp == 1) return base;
        int half = modPow(base, exp / 2);
        long val = ((long) half * half) % MOD_CONST;
        if (exp % 2 == 0) {
            return (int) val;
        } else {
            return (int) ((val * base) % MOD_CONST);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p_input = sc.nextInt();
        int k_input = sc.nextInt();

        if (k_input == 0) {
            System.out.println(modPow(p_input, p_input - 1));
            return;
        }

        if (k_input == 1) {
            System.out.println(modPow(p_input, p_input));
            return;
        }

        int m_counter = 1;
        int t_val = k_input;
        while (true) {
            m_counter++;
            t_val = (int) (((long) t_val * k_input) % p_input);
            if (t_val == 1) {
                System.out.println(modPow(p_input, (p_input - 1) / m_counter));
                return;
            }
        }
    }
}
